/**
 * Where each region's postcodes begin: the step from the last run's first postcode in base 36 in lower case, then
 * the region's code in capitals. 93 runs in all. A postcode is in the state of the last run that begins at or
 * before it; GeoNames' states are those of its last update, so Ladakh's postcodes are in Jammu and Kashmir's runs;
 * a run with the code - is 0 postcodes GeoNames gives no state.
 *
 * @example
 * ```ts
 * IN_POSTCODE_REGION_RUNS.length
 * // → 396
 * ```
 */
const IN_POSTCODE_REGION_RUNS = "";

export { IN_POSTCODE_REGION_RUNS, IN_POSTCODES_PACKED };
